/** One issue to write into a clone, already reset by the service layer. */
export interface ClonedIssueRow {
  readonly number: number;
  readonly title: string;
  readonly description: string | null;
  readonly status: IssueStatus;
  readonly priority: IssuePriority;
  readonly authorId: UserId;
  readonly estimate: number | null;
  readonly dueAt: IsoTimestamp | null;
  readonly labelIds: readonly LabelId[];
}

/**
 * Writes a clone: the project row, then each copied issue with its labels, in
 * one transaction. Either the whole clone lands or none of it does.
 */
export async function insertClonedProject(
  input: CreateProjectInput,
  copies: readonly ClonedIssueRow[],
): Promise<Project> {
  const taken = await listTakenProjectSlugs(input.orgId);
  const slug = uniqueSlug(input.slug, taken);
  const stamp = toIsoTimestamp(new Date());

  return getDb().transaction((tx) => {
    const row = tx
      .insert(projects)
      .values({
        id: newId(),
        orgId: input.orgId,
        name: input.name,
        slug,
        key: input.key,
        description: input.description,
        visibility: input.visibility,
        status: "active",
        leadId: input.leadId,
        color: input.color,
        startsAt: null,
        targetDate: input.targetDate,
        createdAt: stamp,
        updatedAt: stamp,
      })
      .returning()
      .get();

    for (const copy of copies) {
      const issueId = newId();
      tx.insert(issues)
        .values({
          id: issueId,
          orgId: input.orgId,
          projectId: row.id,
          number: copy.number,
          title: copy.title,
          description: copy.description,
          status: copy.status,
          priority: copy.priority,
          authorId: copy.authorId,
          assigneeId: null,
          parentId: null,
          estimate: copy.estimate,
          dueAt: copy.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .run();

      if (copy.labelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            copy.labelIds.map((labelId) => ({
              orgId: input.orgId,
              issueId,
              labelId,
            })),
          )
          .run();
      }
    }

    return toProject(row);
  });
}

