 * Clones a live project into the same workspace under the caller's name, slug
 * and key (ADR 0012). Gates: read on the source, create on the workspace, the
 * source not archived, and the plan's project and per-project issue quotas,
 * all checked before anything is written. The copies are reset: default
 * status, unassigned, no progress stamps, authored by the caller, renumbered
 * from 1 in the source's order. Comments, attachments and links are not copied.
 */
export async function cloneProject(
  actor: Actor,
  input: CloneProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const source = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:read", projectResource(source));
  assertNotArchived("Project", source.id, source);
  assertCan(actor, "project:create", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const usedProjects = await projectRepo.countProjects(input.orgId);
  if (wouldExceedLimit(org.plan, "projects", usedProjects)) {
    throw new Error(
      `Plan ${org.plan} allows ${usedProjects} projects; upgrade to add another`,
    );
  }

  const sourceIssues = input.includeIssues
    ? await issueRepo.listAllLiveIssues(input.orgId, source.id)
    : [];

  // The clone is new, so its issue count starts at zero and the whole batch
  // is checked against the per-project quota at once.
  if (wouldExceedLimit(org.plan, "issuesPerProject", 0, sourceIssues.length)) {
    throw new Error(
      `Plan ${org.plan} allows ${getLimit(org.plan, "issuesPerProject")} issues per project; cloning ${sourceIssues.length} would exceed it`,
    );
  }

  const defaultStatus = issueStatusSchema
    .catch("backlog")
    .parse(org.settings.defaultIssueStatus);

  const copies = sourceIssues.map((issue, index) => ({
    number: index + 1,
    title: issue.title,
    description: issue.description,
    status: defaultStatus,
    priority: issue.priority,
    authorId: actor.userId,
    estimate: issue.estimate,
    dueAt: issue.dueAt,
    labelIds: issue.labelIds,
  }));

  const project = await projectRepo.insertClonedProject(
    {
      orgId: input.orgId,
      name: input.name,
      slug: input.slug,
      key: input.key,
      description: source.description,
      visibility: source.visibility,
      leadId: source.leadId,
      color: source.color,
      targetDate: null,
    },
    copies,
  );

  await emit("project.cloned", {
    ...actorEnvelope(actor),
    projectId: project.id,
    sourceProjectId: source.id,
